#include <algorithm>
#include <iostream>
#include <vector>

struct IsOdd { bool operator()(int value) const { return value % 2 != 0; } };
int main() {
    const std::vector<int> values{1, 2, 3, 4, 5};
    std::cout << std::count_if(values.begin(), values.end(), IsOdd{}) << '\n';
}
